const requestAgentPlanChanges = `-- name: RequestAgentPlanChanges :one
UPDATE agent_plan
SET status = 'changes_requested',
    updated_at = now()
WHERE id = $1 AND status = 'in_review' AND submitted_revision = $2
RETURNING id, workspace_id, issue_id, task_id, agent_id, title, status, revision, submitted_revision, sections, approved_by, approved_at, cancelled_at, created_at, updated_at
`

type RequestAgentPlanChangesParams struct {
	ID       pgtype.UUID `json:"id"`
	Revision pgtype.Int4 `json:"revision"`
}

// changes_requested: in_review -> changes_requested. The revision does NOT
// bump (team-room rule): the agent revises the same plan and resubmits at the
// new revision its own write produced.
func (q *Queries) RequestAgentPlanChanges(ctx context.Context, arg RequestAgentPlanChangesParams) (AgentPlan, error) {
	row := q.db.QueryRow(ctx, requestAgentPlanChanges, arg.ID, arg.Revision)
	var i AgentPlan
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.IssueID,
		&i.TaskID,
		&i.AgentID,
		&i.Title,
		&i.Status,
		&i.Revision,
		&i.SubmittedRevision,
		&i.Sections,
		&i.ApprovedBy,
		&i.ApprovedAt,
		&i.CancelledAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

