const submitAgentPlan = `-- name: SubmitAgentPlan :one
UPDATE agent_plan
SET status = 'in_review',
    submitted_revision = $2,
    task_id = $3,
    updated_at = now()
WHERE id = $1 AND revision = $2
  AND status IN ('draft', 'changes_requested')
RETURNING id, workspace_id, issue_id, task_id, agent_id, title, status, revision, submitted_revision, sections, approved_by, approved_at, cancelled_at, created_at, updated_at
`

type SubmitAgentPlanParams struct {
	ID       pgtype.UUID `json:"id"`
	Revision pgtype.Int4 `json:"revision"`
	TaskID   pgtype.UUID `json:"task_id"`
}

// submit: draft or changes_requested -> in_review, fenced by revision.
// Refusing a double submit at the same revision falls out of the CAS (a plan
// already in_review matches neither status). Re-checking the planning gate is
// the handler's job (it needs issue status + active tasks).
// task_id is refreshed to the submitting task: after a changes_requested →
// resume cycle the caller is a NEW task row, and both the block transition
// and the cancel-while-parked settle must reach the plan through the task
// that is parking NOW, not the original proposer.
func (q *Queries) SubmitAgentPlan(ctx context.Context, arg SubmitAgentPlanParams) (AgentPlan, error) {
	row := q.db.QueryRow(ctx, submitAgentPlan, arg.ID, arg.Revision, arg.TaskID)
	var i AgentPlan
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.IssueID,
		&i.TaskID,
		&i.AgentID,
		&i.Title,
		&i.Status,
		&i.Revision,
		&i.SubmittedRevision,
		&i.Sections,
		&i.ApprovedBy,
		&i.ApprovedAt,
		&i.CancelledAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const updateAgentPlanSection = `-- name: UpdateAgentPlanSection :one
UPDATE agent_plan
SET sections = $2,
    submitted_revision = CASE WHEN status = 'in_review' THEN revision + 1 ELSE submitted_revision END,
    revision = revision + 1,
    updated_at = now()
WHERE id = $1 AND revision = $3
  AND status IN ('draft', 'in_review', 'changes_requested')
RETURNING id, workspace_id, issue_id, task_id, agent_id, title, status, revision, submitted_revision, sections, approved_by, approved_at, cancelled_at, created_at, updated_at
`

type UpdateAgentPlanSectionParams struct {
	ID           pgtype.UUID `json:"id"`
	Sections     []byte      `json:"sections"`
	BaseRevision int32       `json:"base_revision"`
}

// The Human's edit: rewrite the whole sections array and bump the revision,
// fenced on base_revision AND on the statuses an edit is allowed in. When the
// plan is in review the submitted_revision advances with the edit (M-275
// decision 1), so the reviewer's own verdict rides their edit instead of
// 409-ing against a revision their save produced.
func (q *Queries) UpdateAgentPlanSection(ctx context.Context, arg UpdateAgentPlanSectionParams) (AgentPlan, error) {
	row := q.db.QueryRow(ctx, updateAgentPlanSection, arg.ID, arg.Sections, arg.BaseRevision)
	var i AgentPlan
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.IssueID,
		&i.TaskID,
		&i.AgentID,
		&i.Title,
		&i.Status,
		&i.Revision,
		&i.SubmittedRevision,
		&i.Sections,
		&i.ApprovedBy,
		&i.ApprovedAt,
		&i.CancelledAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const withdrawQuestionCardsByTask = `-- name: WithdrawQuestionCardsByTask :exec
UPDATE agent_question_card
SET status = 'withdrawn',
    withdrawn_at = now(),
    updated_at = now()
WHERE task_id = ANY($1::uuid[]) AND status = 'open'
`

// Cancel-while-parked settle (Architect amendment 3): withdrawing every open
// card of a task batch just moved to a terminal status. No-op for tasks that
// never parked (they own no open card).
func (q *Queries) WithdrawQuestionCardsByTask(ctx context.Context, taskIds []pgtype.UUID) error {
	_, err := q.db.Exec(ctx, withdrawQuestionCardsByTask, taskIds)
	return err
}

const writeAgentPlanSection = `-- name: WriteAgentPlanSection :one
UPDATE agent_plan
SET sections = $2,
    revision = revision + 1,
    updated_at = now()
WHERE id = $1 AND revision = $3
  AND status IN ('draft', 'changes_requested')
RETURNING id, workspace_id, issue_id, task_id, agent_id, title, status, revision, submitted_revision, sections, approved_by, approved_at, cancelled_at, created_at, updated_at
`

type WriteAgentPlanSectionParams struct {
	ID           pgtype.UUID `json:"id"`
	Sections     []byte      `json:"sections"`
	BaseRevision int32       `json:"base_revision"`
}

// Section write with the revision fence: base_revision must equal the row's
// current revision or the CAS matches no row (handler → 409 + current
// revision, the port of team-room's stale_doc_revision business outcome).
// The whole sections array is rewritten (single-writer tool contract); the
// revision bumps on every accepted write, which is what fences the next
// write, the submit and the verdict.
func (q *Queries) WriteAgentPlanSection(ctx context.Context, arg WriteAgentPlanSectionParams) (AgentPlan, error) {
	row := q.db.QueryRow(ctx, writeAgentPlanSection, arg.ID, arg.Sections, arg.BaseRevision)
	var i AgentPlan
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.IssueID,
		&i.TaskID,
		&i.AgentID,
		&i.Title,
		&i.Status,
		&i.Revision,
		&i.SubmittedRevision,
		&i.Sections,
		&i.ApprovedBy,
		&i.ApprovedAt,
		&i.CancelledAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
